window.CC_SHOPS=[{"id":"homewood","name":"Homewood","addr":"1724 27th Court South","city":"Homewood, AL 35209","phone":"(205) 879-3244","tel":"+12058793244","hours":[null,[10,18],[10,18],[10,18],[10,18],[10,18],[10,17]],"ll":[33.4766,-86.7952]},{"id":"cahaba-heights","name":"Cahaba Heights","addr":"3179 Cahaba Heights Road","city":"Birmingham, AL 35243","phone":"(205) 967-2003","tel":"+12059672003","hours":[null,[10,18],[10,18],[10,18],[10,18],[10,18],[10,17]],"ll":[33.4637,-86.7299]},{"id":"oak-mountain","name":"Oak Mountain","addr":"2300 Canopy Trail","city":"Pelham, AL 35124","phone":"(205) 987-4043","tel":"+12059874043","hours":[[12,16],[10,18],[10,18],[10,18],[10,18],[10,18],[10,17]],"ll":[33.3297,-86.759]},{"id":"trussville","name":"Trussville","addr":"183 Main Street","city":"Trussville, AL 35173","phone":"(205) 655-6090","tel":"+12056556090","hours":[null,null,[10,18],[10,18],[10,18],[10,17],[10,16]],"ll":[33.6197,-86.6089]},{"id":"gadsden","name":"Gadsden","addr":"1000 Noccalula Rd","city":"Gadsden, AL 35904","phone":"(205) 615-3177","tel":"+12056153177","hours":[null,null,[10,18],[10,18],[10,18],[10,18],[10,17]],"ll":[34.0386,-86.0216]},{"id":"ridebhm","name":"RideBHM demo center","addr":"2800 Portofino Drive","city":"Birmingham, AL 35211","phone":"","tel":"","hours":[[10,18],[14,18],[14,18],[14,18],[14,18],[10,18],[10,18]],"ll":[33.43,-86.88],"demo":true}];
window.CC_CREW=[{"n":"Gene","a":{"mem":"Riding the MS450","snack":"In a car: Grandma's Cookies. On a bike: cashews.","animal":"Cat","why":"Keeps me active and engaged in the sport"}},{"n":"Jonathan","a":{"mem":"Too many to choose just one.","snack":"Anything with chocolate.","animal":"Hawk","why":"Cahaba is like family. Such a great, fun crew of people to spend my days with. I also enjoy the mechanical side of working on bicycles."}},{"n":"Virginia","a":{"mem":"My best memory on a bike ranges from bikes I got for Christmas as a kid, to mtn bike rides with friends, road rides with friends or solo rides to clear my head. Most every ride is a great memory.","snack":"Road trip go to snack when I am on my bike, is a payday bar...no matter how hot it is out, those things barely melt (especially if you get hold of an out of date one)","animal":"I identify as a cat. Although, I have been called a shark since I have started at Cahaba. Connecting people to bikes is my chum in the water.","why":"I work at Cahaba purely by accident. I asked Faris if he needed help at Christmas four years ago. I thought it would be a super fun and easy job - boy, was I wrong. It is super fun, but the learning curve and the constant changes is way more challenging than I would have imagined."}},{"n":"Kenny","a":{"mem":"My first time on a mountain bike climbing Mustard Road in the foothills of California questioning why I ever decided to start cycling while my in-shape friends sped to the top. After walking the second half to the top, I knew my life would forever change!","snack":"Fritos or Cheddar Jack Cheez-its (the only good Cheez-it)","animal":"Great Dane - clumsy, derpy, and trip over myself but evenly tempered","why":"To be a part of a growing community of people who share the love for our lifestyle!"}},{"n":"Chris B","a":{}},{"n":"Daniel","a":{"mem":"We took a family trip several years ago to Huntington Beach, Ca via Phoenix, AZ I got to ride thru the desert and the PCH in the same trip.","snack":"Peanut m&ms","animal":"Some kind of a woodland critter maybe a racoon or a opossum."}},{"n":"Liz","a":{"mem":"It's hard to choose but I will have to say that the first time our youngest daughter PJ got to ride with Dan on the Shotgun seat has to be a fan favorite. Thankfully I caught some of her joy on video!","snack":"Duke's Hatch Green Chile Shorty Sausages or Cajun Boiled Peanuts","animal":"Dragonflies!! I just think that they are really cool."}},{"n":"Chris T","a":{"mem":"Took a trip in the early 2000s in my van riding trails from here to colorado.","snack":"Any sour candy and shelled sunflower seeds.","animal":"Kitty cat."}},{"n":"Chris S","a":{"mem":"Taking the training wheels off of my bike and experiencing the freedom of going \"fast\" and exploring the neighborhood.","snack":"Payday, you have just the essentials -- caramel and peanuts, sweet and salty...best bike riding fuel in my book.","animal":"Without a doubt dogs! They are incredibly loyal, always happy to see you, have unique personalities, and they always bring a smile to my face. My spirit animal for sure."}},{"n":"Chris W","a":{"mem":"Riding Road Bikes downtown Birmingham during the Covid Pandemic.... Zero cars on the road, it was so unreal not to witness any traffic.","snack":"Oh Snap, Dilly Bites Dill Pickle Snacking Cuts.","animal":"I would be a shark if I were to choose any animal in the animal kingdom. A shark in the water always has to be moving forward, and I feel that accurately represents how I am in a work environment. I'm always looking for an opportunity to progress a project, and when I complete one, I'm eager to get started on the next as quickly as possible so that I'm always busy and moving ahead."}},{"n":"Joe D","a":{"mem":"Finishing a long ride. Doing something on a bike that I haven't done before","snack":"Peanuts","animal":"A dog"}},{"n":"Jon","a":{"mem":"Riding mountain bikes in Utah. Great views.","snack":"Combos, any flavor","animal":"Dog, because I like belly rubs."}},{"n":"Andrew","a":{"mem":"Riding with Barry Bonds on The Golden Gate Bridge.","snack":"Nerds Clusters for sure","animal":"A Wombat"}},{"n":"Jason","a":{}},{"n":"Deason","a":{"snack":"Reeses cups, bonus points if they are cold.","why":"The customers, I have made countless friends and met some amazing people that come to our stores."}}];
